class Solution:
    def maxScore(self, nums: List[int]) -> int:
        from math import gcd
        def score(arr):
            if not arr:
                return 0
            g, l = 0, 1
            for x in arr:
                g = gcd(g, x)
                l = l * x // gcd(l, x)
            return g * l
        ans = score(nums)
        for i in range(len(nums)):
            ans = max(ans, score(nums[:i] + nums[i+1:]))
        return ans

