class Solution {
    long long score(vector<int>& arr, int skip) {
        long long g = 0, l = 1;
        bool any = false;
        for (int i = 0; i < (int)arr.size(); i++) {
            if (i == skip) continue;
            any = true;
            g = __gcd(g, (long long)arr[i]);
            l = l / __gcd(l, (long long)arr[i]) * arr[i];
        }
        return any ? g * l : 0;
    }
public:
    long long maxScore(vector<int>& nums) {
        long long ans = score(nums, -1);
        for (int i = 0; i < (int)nums.size(); i++)
            ans = max(ans, score(nums, i));
        return ans;
    }
};

