class Solution {
    private long score(int[] arr, int skip) {
        long g = 0, l = 1;
        boolean any = false;
        for (int i = 0; i < arr.length; i++) {
            if (i == skip) continue;
            any = true;
            g = gcd(g, arr[i]);
            l = l / gcd(l, arr[i]) * arr[i];
        }
        return any ? g * l : 0;
    }
    private long gcd(long a, long b) { return b == 0 ? a : gcd(b, a % b); }
    public long maxScore(int[] nums) {
        long ans = score(nums, -1);
        for (int i = 0; i < nums.length; i++)
            ans = Math.max(ans, score(nums, i));
        return ans;
    }
}

