public:
    long long maxScore(vector<int>& nums) {
        int n = nums.size();
        vector<long long> pg(n+1, 0), pl(n+1, 1), sg(n+1, 0), sl(n+1, 1);
        for (int i = 0; i < n; i++) {
            pg[i+1] = __gcd(pg[i], (long long)nums[i]);
            pl[i+1] = pl[i] / __gcd(pl[i], (long long)nums[i]) * nums[i];
        }
        for (int i = n - 1; i >= 0; i--) {
            sg[i] = __gcd(sg[i+1], (long long)nums[i]);
            sl[i] = sl[i+1] / __gcd(sl[i+1], (long long)nums[i]) * nums[i];
        }
        long long ans = sl[0] * sg[0];
        for (int i = 0; i < n; i++) {
            long long l = pl[i] / __gcd(pl[i], sl[i+1]) * sl[i+1];
            long long g = __gcd(pg[i], sg[i+1]);
            ans = max(ans, l * g);
        }
        return ans;
    }
};

